// Hand-written `@cloudflare/workers-types` stub: the per-scope objects (Durable
// Objects) a worker reaches through a namespace, and the base class of one.

declare interface DurableObjectId {
  toString(): string;
}

declare interface DurableObjectState {
  readonly id: DurableObjectId;
  blockConcurrencyWhile<T>(callback: () => Promise<T>): Promise<T>;
}

declare interface Fetcher {
  fetch(input: string | Request, init?: RequestInit): Promise<Response>;
}

/** A stub: `fetch`, and each method of the class, called over the wire. */
declare type DurableObjectStub<T = undefined> = Fetcher & (T extends object ? Omit<T, 'fetch'> : {});

declare interface DurableObjectNamespace<T = undefined> {
  idFromName(name: string): DurableObjectId;
  idFromString(id: string): DurableObjectId;
  newUniqueId(): DurableObjectId;
  get(id: DurableObjectId): DurableObjectStub<T>;
  getByName(name: string): DurableObjectStub<T>;
}

/** What a plain worker's default export is: its own `fetch`. */
declare interface ExportedHandler<Env = unknown> {
  fetch?(request: Request, env: Env): Response | Promise<Response>;
}

declare module 'cloudflare:workers' {
  export abstract class DurableObject<Env = unknown> {
    protected readonly ctx: DurableObjectState;
    protected readonly env: Env;
    constructor(ctx: DurableObjectState, env: Env);
  }
}
